'use client';

import { useState, useRef, useEffect } from 'react';
import { motion as Motion, AnimatePresence } from 'motion/react';
import { Check, Copy, ChevronDown, ChevronUp, RotateCcw, Maximize2, Minimize2, Volume2, VolumeX } from 'lucide-react';

export interface SpotifyData {
  isPlaying: boolean;
  title: string;
  artist: string;
  album: string;
  albumArt: string;
  songUrl: string;
}

export function useSpotify() {
  const [data, setData] = useState<SpotifyData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSpotify = async () => {
      try {
        const res = await fetch('/api/spotify');
        if (!res.ok) throw new Error('Failed to fetch');
        const json = await res.json();
        setData(json);
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    };
    fetchSpotify();
    const interval = setInterval(fetchSpotify, 10000);
    return () => clearInterval(interval);
  }, []);

  return { data, loading, error };
}

export default function MusicPlayer() {
  const { data, loading } = useSpotify();
  const [isExpanded, setIsExpanded] = useState(false);

  const song = data || {
    isPlaying: true,
    title: 'Lofi Beats',
    artist: 'Chillhop Music',
    album: 'Lofi Study Sessions',
    albumArt: 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=300&auto=format&fit=crop',
    songUrl: 'https://open.spotify.com',
  };

  return (
    <div className="relative z-40 my-4 h-[88px] w-full select-none flex justify-center">
      <div className="relative flex justify-center w-[270px]">
        <Motion.div
          layout
          onClick={() => setIsExpanded((prev) => !prev)}
          animate={{ height: isExpanded ? 284 : 88 }}
          transition={{ type: 'spring', stiffness: 380, damping: 46 }}
          className="absolute bottom-0 w-[270px] cursor-pointer overflow-hidden rounded-[24px] border border-neutral-800 bg-neutral-950 p-3 shadow-2xl text-white"
        >
          <div className="flex items-center gap-3">
            <img
              src={song.albumArt}
              alt={song.title}
              className={`size-14 rounded-full object-cover ${song.isPlaying ? 'animate-[spin_10s_linear_infinite]' : ''}`}
            />
            <div className="flex flex-col truncate">
              <span className="truncate text-sm font-semibold">{song.title}</span>
              <span className="truncate text-xs text-neutral-400">{song.artist}</span>
            </div>
          </div>
        </Motion.div>
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
